        let stderr = child.stderr.take().ok_or_else(|| ModelError::Provider {
            provider: PROVIDER.to_owned(),
            message: "failed to open shell provider stderr".to_owned(),
            retryable: false,
        })?;

        Ok(Box::pin(stream_output(stdout, stderr, child)))
    }
